// isAccordion — поведение приложения; preExpanded задаёт только начальное раскрытие. Для rich content передайте ReactNode overrides, сохранив ссылки, форматирование и семантику.
// Для закрытых/сложных ответов нужен настоящий answer приложения; текст из другого master не подставляется.
function Example({ content, isAccordion, onItemClick }: {
    content: [{ id: FAQItemType['id']; question?: FAQItemType['question']; answer: NonNullable<FAQItemType['answer']> }, { id: FAQItemType['id']; question?: FAQItemType['question']; answer: NonNullable<FAQItemType['answer']> }, { id: FAQItemType['id']; question?: FAQItemType['question']; answer: NonNullable<FAQItemType['answer']> }, { id: FAQItemType['id']; question?: FAQItemType['question']; answer: NonNullable<FAQItemType['answer']> }];
    isAccordion: NonNullable<FAQProps['isAccordion']>;
    onItemClick?: FAQProps['onItemClick'];
}) {
    const ids = content.map(item => item.id);
    if (ids.some(id => !id.trim()) || new Set(ids).size !== ids.length) throw new Error('FAQ item IDs must be nonempty and unique');
    return <FAQ
        isAccordion={isAccordion}
        onItemClick={onItemClick}
        preExpanded={[]}
        hideBorderForItems={[]}
        items={[{ id: content[0].id, question: (content[0].question === undefined ? "Title" : content[0].question), answer: content[0].answer },{ id: content[1].id, question: (content[1].question === undefined ? "Title" : content[1].question), answer: content[1].answer },{ id: content[2].id, question: (content[2].question === undefined ? "Title" : content[2].question), answer: content[2].answer },{ id: content[3].id, question: (content[3].question === undefined ? "Title" : content[3].question), answer: content[3].answer },]}
    />;
}

